import ast
import json
from collections import Counter

def task_func(file_pointer):
    data = json.load(file_pointer)
    keys = []
    for entry in data:
        if isinstance(entry, str):
            entry = ast.literal_eval(entry)
        keys.extend(entry.keys())
    return Counter(keys)

