    def remove_none(obj):
        if isinstance(obj, dict):
            return {k: remove_none(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [remove_none(item) for item in obj if item is not None]
        else:
            return obj
    def replace_email(obj):
        if isinstance(obj, dict):
            return {k: replace_email(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_email(item) for item in obj]
        elif isinstance(obj, str):
            return re.sub(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', REPLACE_NONE, obj)
        else:
            return obj
    data = json.loads(json_str)
    data = remove_none(data)
    data = replace_email(data)
    def flatten(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from flatten(v)
        elif isinstance(obj, list):
            for v in obj:
                yield from flatten(v)
        else:
            yield obj
    flat = list(flatten(data))
    value_counts = Counter(flat)
    return {"data": data, "value_counts": value_counts}
