import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    for key in key_path:
        data = data[key]
    if not isinstance(data, list):
        raise ValueError("Data is not a list")
    if not data:
        raise ValueError("No data found")
    numeric_data = []
    for item in data:
        try:
            numeric_data.append(float(item))
        except (ValueError, TypeError):
            raise ValueError("Non-numeric data encountered")
    fig, ax = plt.subplots()
    sns.boxplot(data=numeric_data, ax=ax)
    ax.set_title('Boxplot of Extracted Data')
    return fig
